void nn_forward(f32 out[2], const f32 raw_8d[8]) {
    f32 h1[NN_H1_DIM];
    f32 h2[NN_H2_DIM];

    /* fc1: 8->80 ReLU (normalization fused) */
    for (int i = 0; i < NN_H1_DIM; i++) {
        f32 sum = fc1_bias[i];
        for (int j = 0; j < NN_IN_DIM; j++)
            sum += fc1_weight[i * NN_IN_DIM + j] * raw_8d[j];
        h1[i] = sum > 0.0f ? sum : 0.0f;
    }

    /* fc2: 80->48 ReLU */
    for (int i = 0; i < NN_H2_DIM; i++) {
        f32 sum = fc2_bias[i];
        for (int j = 0; j < NN_H1_DIM; j++)
            sum += fc2_weight[i * NN_H1_DIM + j] * h1[j];
        h2[i] = sum > 0.0f ? sum : 0.0f;
    }

    /* fc3: 48->2 (raw output, clamp) */
    f32 raw_a = fc3_bias[0];
    f32 raw_o = fc3_bias[1];
    for (int j = 0; j < NN_H2_DIM; j++) {
        raw_a += fc3_weight[0 * NN_H2_DIM + j] * h2[j];
        raw_o += fc3_weight[1 * NN_H2_DIM + j] * h2[j];
    }
    out[0] = raw_a < -NN_A_MAX ? -NN_A_MAX : (raw_a > NN_A_MAX ? NN_A_MAX : raw_a);
    out[1] = raw_o < -NN_O_MAX ? -NN_O_MAX : (raw_o > NN_O_MAX ? NN_O_MAX : raw_o);
}
